.card {
  font-family: arial;
  font-size: 20px;
  text-align: center;
  color: black;
  background-color: white;

margin:2% auto;
width: fit-content;
/*
edited by TeamAnki
*/
}

.blessingTitle{
background-color: orange;
padding:10px;
width: 100%;

position:relative;
top: -10px;
left: -10px;

border-top-left-radius: 16px;
border-top-right-radius: 16px;
font-family:Arial Rounded MT Bold;
font-family: Berlin Sans FB;
font-family: Californian FB;
font-family:Comic Sans MS;
font-family: Lucida Calligraphy;
}

.blessingTitle a{color:blue}

.container{
	padding: 10px;
	border: 2px solid orange;
	border-radius:20px;
	box-shadow: 0 4px  8px 1px orange;
}

.small {
  font-size: 15px;
}

table, td, th {

  border-collapse: collapse;
  padding: 5px;
}

table {
background-color: #eee;
  display: inline-block;
  text-align: left;
border-radius: 10px;
margin:10px;
}

#atable tr:first-child{
display: block;
border-radius: 10px 10px 0 0;
}

#atable tr:last-child{
display: block;
border-radius: 0 0 10px 10px;
}

label {
	color:black;
  margin-left: 0.4em;
}

.correct {
  background-color: lime;
}

.nightMode .correct {
  background-color: lime;
}

.wrong {
  background-color: OrangeRed;
}

.hidden {
  /*
  This block is from Glutanimate's Cloze Overlapper card template.
  The Cloze Overlapper card template is licensed under the CC BY-SA 4.0
  license (https://creativecommons.org/licenses/by-sa/4.0/).
  */
  /* guarantees a consistent width across front and back */
  font-weight: bold;
  display: block;
  line-height: 0;
  height: 0;
  overflow: hidden;
  visibility: hidden;
}

.blessingTitle { direction: rtl; }
